// Patches the v3 table with the K1 n-up literals from t8v3. Does not overwrite v3.
// Do not edit this file after it has run.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const src = JSON.parse(readFileSync(resolve('work/out/accept-table-t8-v3.json'), 'utf8'));
const DIRECT = '9d6a92dc9914061304a8f94e2515a22b5fd6ba2846405649f740cc62282aea02';
const halfUp2 = JSON.parse(JSON.stringify(src.presets.halfUp));
halfUp2.k5962 = halfUp2.k5962.slice();
halfUp2.k5962[0] = 292;
halfUp2.k88b2 = [292];
src.presets.halfUp2 = halfUp2;
src.table = 'accept-table-t8-v4';
for (const step of src.steps) {
  if (step.id !== 'n-up') continue;
  step.expect.title = DIRECT;
  step.expect.half = { preset: 'halfUp2' };
}
writeFileSync(resolve('work/out/accept-table-t8-v4.json'), JSON.stringify(src, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, k5962: halfUp2.k5962, k88b2: halfUp2.k88b2 }) + '\n');
